package com.safebox.self_storage.controller;
import com.safebox.self_storage.dto.support.*;import com.safebox.self_storage.service.StaffScopeService;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/staff") public class StaffScopeController{private final StaffScopeService s;public StaffScopeController(StaffScopeService s){this.s=s;}@GetMapping public List<StaffScopeView> staff(){return s.staff();}@PostMapping("/{staffId}/facilities") public StaffScopeView grant(@PathVariable UUID staffId,@Valid @RequestBody StaffFacilityAssignmentRequest r){return s.grant(staffId,r);}@DeleteMapping("/{staffId}/facilities/{facilityId}") public StaffScopeView revoke(@PathVariable UUID staffId,@PathVariable UUID facilityId){return s.revoke(staffId,facilityId);}}
